state=loadState();
function adminAuthorized(){const user=Auth.currentAuth(state);if(user?.role==='admin')return true;document.getElementById('app').innerHTML='';location.replace('./?next=admin#login');return false;}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="logout"]')){e.preventDefault();e.stopImmediatePropagation();Auth.clearAuth();location.href='./#login';return;}if(!adminAuthorized()){e.preventDefault();e.stopImmediatePropagation();}},true);
document.addEventListener('submit',e=>{if(!adminAuthorized()){e.preventDefault();e.stopImmediatePropagation();}},true);
let page='deals',filters={q:'',dealStatus:'',paymentStatus:'',category:'',subcategory:'',scope:'all',sort:'newest'},pageNo=1,drawer=null,detailTab='overview',modal=null,ticketId='AN-108',inboxFilter='open',inboxSearch='',drafts={};
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',deal:'M7 3h10l4 4v14H3V3h4 M7 3v5h10V3 M7 13h10 M7 17h6',wallet:'M3 6h17v15H3z M3 6V3h14v3 M15 11h6v5h-6z',chat:'M21 11a8 8 0 0 1-8 8H8l-5 3V11a9 9 0 0 1 18 0z M7 10h10 M7 14h6',search:'m21 21-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M5 12h14 m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',alert:'m12 3 10 18H2L12 3 M12 9v5 M12 17v1',close:'m6 6 12 12 M6 18 18 6',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',lock:'M6 10V7a6 6 0 0 1 12 0v3 M4 10h16v12H4z M12 14v4',help:'M9 8a3 3 0 0 1 6 0c0 3-3 2-3 5 M12 17h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 3a4 4 0 0 1 0 8 M18 15a4 4 0 0 1 4 4v2',building:'M4 22V3h12v19 M16 10h5v12 M8 7h4 M8 11h4 M8 15h4 M8 22v-3h4v3',refresh:'M20 7v5h-5 M4 17v-5h5 M5 7a8 8 0 0 1 13-2l2 2 M4 17l2 2a8 8 0 0 0 13-2',send:'m22 2-7 20-4-9-9-4L22 2z M11 13 22 2',external:'M14 3h7v7 M21 3 10 14 M10 3H3v18h18v-7',note:'M4 3h16v18H4z M8 8h8 M8 12h8 M8 16h5',euro:'M18 5a7 7 0 1 0 0 14 M3 10h11 M3 14h11',filter:'M3 5h18 M6 12h12 M10 19h4',back:'M19 12H5 m6-6-6 6 6 6'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const initials=s=>s.split(' ').slice(0,2).map(w=>w[0]).join('');
const pill=(v,type='deal')=>`<span class="badge ${v}"><i></i>${esc((type==='payment'?PL:DL)[v])}</span>`;
const option=(value,label,selected)=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`;
function save(){state.lastSaved=new Date().toISOString();try{saveState(state);storageOK=true;}catch{storageOK=false;}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function render(){if(!adminAuthorized())return;const active=document.activeElement,focusId=active?.id,pos=active?.selectionStart;const s=stats(state);$('#app').innerHTML=`
 <aside class="sidebar"><a class="brand" href="#deals" aria-label="BuyMe Admin Startseite"><img class="brand-logo" src="./assets/buyme-logo-light.svg" width="239" height="68" alt="BuyMe"></a><div class="brand-caption">ADMIN COCKPIT</div><a class="admin-home-link" href="./">← Zur BuyMe-Testplattform</a>
 <div class="workspace"><span class="workspace-icon">B</span><div><strong>BuyMe Plattform</strong><small>Administration</small></div>${icon('lock')}</div><div class="nav-label">ARBEITSBEREICH</div>
 <nav aria-label="Hauptnavigation">${[['deals','deal','Deals',s.total],['orders','deal','Bestellungen',(state.orders||[]).length],['payments','wallet','Zahlungen',state.deals.filter(d=>!['paid','stopped'].includes(d.payment)).length],['inbox','chat','Anfragen',s.open],['reviews','check','Bewertungen',state.reviews.length],['offers','grid','Angebote',state.offers.filter(o=>o.status==='pending').length],['people','users','Konten',state.members.length+state.providers.length],['legal','lock','Recht & Freigabe',(state.legalRequests||[]).length]].map(([p,i,t,n])=>`<button data-nav="${p}" aria-label="${t} (${n})" title="${t}" class="nav-item ${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}<span>${t}</span><b>${n}</b></button>`).join('')}</nav>
 <div class="side-bottom"><div class="demo-card"><span class="live-dot"></span><strong>Dein privater Prototyp</strong><p>Beispieldaten. Sicher ausprobieren und Abläufe prüfen.</p><button data-action="info">So funktioniert’s ${icon('arrow')}</button></div><button class="help-link" data-action="info">${icon('help')} Hilfe & Demo-Info</button><div class="profile"><span class="avatar">EA</span><div><strong>Ejdat Akyol</strong><small>Plattformbetreiber</small></div><span class="profile-dot"></span></div></div></aside>
 <div class="shell"><header class="topbar"><div class="breadcrumb"><span>Arbeitsbereich</span>${icon('chevron')}<strong>${{legal:'Recht & Freigabe',orders:'Bestellungen',deals:'Deals',payments:'Zahlungen',inbox:'Anfragen',offers:'Angebote',people:'Konten',reviews:'Bewertungen'}[page]}</strong></div><div class="topbar-right"><span class="private-tag">${icon('lock')} Privat</span><span class="divider"></span><a class="admin-platform-link" href="./#market">Marktplatz</a><button class="text-button" data-action="logout">Abmelden</button><span class="avatar small">EA</span></div></header>
 <main id="main" tabindex="-1"><div class="page-heading"><div><div class="eyebrow">BUYME ADMINISTRATION</div><h1>${{legal:'Recht & Freigabe',orders:'Käufe & Bestellungen',deals:'Dealübersicht',payments:'Zahlungen & Cashback',inbox:'Anfragen',offers:'Angebote & Freigaben',people:'Mitglieder & Anbieter',reviews:'Bewertungen & Streitfälle'}[page]}</h1><p>${{legal:'Rechtstexte, lokale Testmeldungen und offene Aufgaben für den Echtbetrieb.',orders:'Kaufzahlungen aller Anbieter prüfen und die zugehörigen Deals öffnen.',deals:'Alle Abschlüsse, Zahlungen und Rückfragen an einem Ort.',payments:'Vom Anbieterbudget bis zur Auszahlung an das Mitglied.',inbox:'Fragen klären. Vorgänge nachvollziehen. Gemeinsam weiterkommen.',offers:'Neue Angebote prüfen, freigeben und Bedingungen nachvollziehen.',people:'Demokonten und Anbieterstatus verwalten.',reviews:'Beide Bewertungen vergleichen, Dealgrundlage prüfen und Streitfälle intern dokumentieren.'}[page]}</p></div>${['orders','offers','people','reviews'].includes(page)?`<a class="button white" href="./">Plattform öffnen ${icon('arrow')}</a>`:page==='inbox'?`<div class="heading-note">${icon('chat')} <span><strong>${s.open} offene Anfragen</strong><small>Mit jedem Deal verknüpft</small></span></div>`:`<button class="button white" data-action="export">${icon('download')} CSV exportieren</button>`}</div>
 <div class="prototype-line">${icon('lock')} <span><strong>Privater Prototyp</strong> · Fiktive Beispieldaten. Antworten und Statusänderungen werden nur in diesem Browser gespeichert.</span><button data-action="info">Details</button></div>
 ${!storageOK?'<div class="storage-error" role="alert">Der Browserspeicher ist nicht verfügbar. Änderungen bleiben nur bis zum Neuladen erhalten.</div>':''}
 ${page==='legal'?legalAdminPage(state,Auth.currentAuth(state)):page==='orders'?ordersPage(state,'admin','ADMIN-1',null,adminOrderFilters):page==='reviews'?adminReviewsPage(state,adminReviewFilters):page==='offers'?offerModerationPage():page==='people'?peoplePage():page==='inbox'?inboxPage():page==='payments'?paymentsPage():dealsPage()}
 <footer><span>BuyMe · Geld statt Punkte.</span><span>${storageOK?'Lokal gespeichert':'Speichern eingeschränkt'} <i class="save-dot"></i></span></footer>${legalFooter()}</main></div>`;
 renderOverlay();
 if(focusId&&document.getElementById(focusId)){const el=document.getElementById(focusId);el.focus();if(typeof pos==='number'&&el.setSelectionRange)try{el.setSelectionRange(pos,pos);}catch{}}
}
function statCard(label,value,sub,i,cls=''){return `<div class="stat"><div class="stat-top"><span>${label}</span><span class="stat-icon ${cls}">${icon(i)}</span></div><div class="stat-value">${value}</div><div class="stat-sub">${sub}</div></div>`;}
function dealsPage(){const s=stats(state);return `<section class="stats" aria-label="Deal-Kennzahlen">${statCard('Deals gesamt',s.total,'Über alle Kategorien','deal')}${statCard('Aktive Deals',s.active,'In Annahme, Prüfung oder bestätigt','clock')}${statCard('Cashback offen',money(s.outstanding),'Inklusive noch nicht freigegebener Prämien','wallet')}${statCard('Offene Rückfragen',s.open,'Warten auf Klärung','chat','amber')}</section>
 <div class="attention-banner"><span class="attention-icon">${icon('alert')}</span><div><strong>${s.attention} Deals brauchen deine Aufmerksamkeit</strong><span>${s.open} offene Rückfragen · ${state.deals.filter(d=>d.payment==='failed').length} fehlgeschlagene Auszahlung</span></div><button data-action="attention">Vorgänge prüfen ${icon('arrow')}</button></div>
 <section class="table-card"><div class="card-top"><h2>Alle Deals <span class="count">${s.total}</span></h2><span class="subtle">Beispieldaten · Oktober 2026</span></div><div class="tabs" aria-label="Dealansicht">${[['all','Alle Deals',s.total],['attention','Handlungsbedarf',s.attention],['completed','Abgeschlossen',state.deals.filter(d=>d.status==='completed').length]].map(([v,t,n])=>`<button data-scope="${v}" class="tab ${filters.scope===v?'selected':''}" aria-pressed="${filters.scope===v}">${t}<span>${n}</span></button>`).join('')}</div>${filterBar()}${dealTable(false)}</section>`;}
function filterBar(){return `<div class="filter-bar"><label class="searchbox">${icon('search')}<input id="deal-search" aria-label="Deals durchsuchen" placeholder="Deal-ID, Mitglied oder Anbieter suchen …" value="${esc(filters.q)}"><kbd>/</kbd></label><div class="filter-selects">${page==='deals'?`<label><span class="sr-only">Dealstatus filtern</span><select id="filter-deal" aria-label="Dealstatus filtern">${option('','Alle Dealstatus',filters.dealStatus)}${Object.entries(DL).map(([k,v])=>option(k,v,filters.dealStatus)).join('')}</select></label>`:''}<label><span class="sr-only">Zahlungsstatus filtern</span><select id="filter-payment" aria-label="Zahlungsstatus filtern">${option('','Alle Zahlungsstatus',filters.paymentStatus)}${Object.entries(PL).map(([k,v])=>option(k,v,filters.paymentStatus)).join('')}</select></label><label><span class="sr-only">Kategorie filtern</span><select id="filter-category" aria-label="Kategorie filtern">${option('','Alle Kategorien',filters.category)}${CATEGORIES.map(v=>option(v,v,filters.category)).join('')}</select></label><label><span class="sr-only">Unterkategorie filtern</span><select id="filter-subcategory" aria-label="Unterkategorie filtern" ${!subcategoriesFor(filters.category).length?'disabled':''}>${option('','Alle Unterkategorien',filters.subcategory)}${subcategoriesFor(filters.category).map(v=>option(v,v,filters.subcategory)).join('')}</select></label></div></div><div class="result-bar"><span><strong>${selectDeals(state,filters).length}</strong> Deals gefunden ${[filters.q,filters.dealStatus,filters.paymentStatus,filters.category,filters.subcategory].some(Boolean)||filters.scope!=='all'?'<button class="text-button" data-action="clear">Filter zurücksetzen</button>':''}</span><label class="sort-label">Sortieren: <select id="sort" aria-label="Sortierung">${option('newest','Neueste zuerst',filters.sort)}${option('oldest','Älteste zuerst',filters.sort)}${option('cashback','Höchstes Cashback',filters.sort)}</select></label></div>`;}
function dealTable(payments){const list=selectDeals(state,filters),max=Math.max(1,Math.ceil(list.length/8));pageNo=Math.min(pageNo,max);const slice=list.slice((pageNo-1)*8,pageNo*8);return `<div class="table-scroll"><table><thead><tr><th>${payments?'Deal / Mitglied':'Deal / Angebot'}</th><th>${payments?'Anbieter':'Beteiligte'}</th><th>Cashback</th><th>${payments?'Budgetdeckung':'Dealstatus'}</th><th>Zahlungsstatus</th><th>${payments?'Referenz':'Erstellt'}</th><th><span class="sr-only">Öffnen</span></th></tr></thead><tbody>${slice.map(d=>`<tr><td><button class="deal-link" data-open="${d.id}" data-detail="${payments?'payment':'overview'}">${d.id}${attention(state,d)?'<span class="attention-dot" aria-label="Handlungsbedarf"></span>':''}</button><div class="cell-sub">${userText(payments?d.user:d.offer)}</div>${!payments?`<span class="category">${esc(classificationLabel(d))}</span>`:''}</td><td>${payments?`<strong class="table-provider">${userText(d.provider)}</strong>`:`<div class="member"><span class="avatar tiny avatar-${d.userId.slice(-1)}">${initials(d.user)}</span>${userText(d.user)}</div><div class="cell-sub provider-name">${userText(d.provider)}</div>`}</td><td class="amount">${money(d.cashback)}</td><td>${payments?`<span class="funded ${d.funded?'yes':''}">${icon(d.funded?'check':'clock')}${d.funded?'Gedeckt':'Offen'}</span>`:pill(d.status)}</td><td>${pill(d.payment,'payment')}</td><td class="muted ${payments?'ref':''}">${payments?d.paymentRef:date(d.created)}</td><td><button class="row-arrow" data-open="${d.id}" data-detail="${payments?'payment':'overview'}" aria-label="Deal ${d.id} öffnen">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table>${!slice.length?`<div class="empty">${icon('search')}<h3>Keine passenden Deals</h3><p>Versuche einen anderen Suchbegriff oder setze die Filter zurück.</p><button class="button primary" data-action="clear">Filter zurücksetzen</button></div>`:''}</div><div class="pagination"><span>${list.length?(pageNo-1)*8+1:0}–${Math.min(pageNo*8,list.length)} von ${list.length} Deals</span><div><button class="page-arrow" data-page="${pageNo-1}" ${pageNo<=1?'disabled':''} aria-label="Vorherige Seite">${icon('back')}</button>${Array.from({length:max},(_,i)=>`<button data-page="${i+1}" class="page-number ${pageNo===i+1?'selected':''}" ${pageNo===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}<button class="page-arrow" data-page="${pageNo+1}" ${pageNo>=max?'disabled':''} aria-label="Nächste Seite">${icon('arrow')}</button></div></div>`;}
function paymentsPage(){return `<section class="stats">${[['pending','Ausstehend','clock'],['released','Freigegeben','check'],['processing','In Auszahlung','wallet'],['failed','Fehlgeschlagen','alert']].map(([v,l,i])=>{const ds=state.deals.filter(d=>d.payment===v);return statCard(l,money(ds.reduce((a,d)=>a+d.cashback,0)),ds.length+' '+(ds.length===1?'Zahlung':'Zahlungen'),i,v==='failed'?'red':'');}).join('')}</section><div class="finance-note">${icon('help')} <span>Cashback wird vom Anbieter finanziert. Die Servicegebühr trägt der Anbieter zusätzlich. Alle Zahlungsdaten und Freigaben sind simuliert.</span></div><section class="table-card"><div class="card-top"><h2>Zahlungsübersicht <span class="count">${state.deals.length}</span></h2><span class="subtle">Kein Zugriff auf echte Zahlungsdienste</span></div>${filterBar()}${dealTable(true)}</section>`;}
function filteredTickets(){const q=inboxSearch.trim().toLowerCase();return state.tickets.filter(t=>(inboxFilter==='all'||t.status===inboxFilter)&&(!q||[t.id,t.subject,t.dealId,state.deals.find(d=>d.id===t.dealId).user,state.deals.find(d=>d.id===t.dealId).provider].some(s=>s.toLowerCase().includes(q)))).sort((a,b)=>b.messages.at(-1).at.localeCompare(a.messages.at(-1).at));}
function inboxPage(){const list=filteredTickets();const selected=list.find(t=>t.id===ticketId)||list[0];if(selected)ticketId=selected.id;return `<section class="inbox"><div class="inbox-list"><div class="inbox-list-head"><h2>Posteingang <span class="count">${state.tickets.length}</span></h2><label class="searchbox">${icon('search')}<input id="inbox-search" aria-label="Anfragen durchsuchen" placeholder="Anfragen durchsuchen …" value="${esc(inboxSearch)}"></label><div class="inbox-tabs">${[['open','Offen'],['resolved','Erledigt'],['all','Alle']].map(([v,l])=>`<button data-inbox-filter="${v}" class="${inboxFilter===v?'selected':''}" aria-pressed="${inboxFilter===v}">${l}</button>`).join('')}</div></div><div class="ticket-list">${list.map(t=>{const d=state.deals.find(x=>x.id===t.dealId);return `<button class="ticket ${t.id===selected?.id?'selected':''}" data-ticket="${t.id}"><div class="ticket-top"><span>${t.id} · ${t.role==='user'?'Mitglied':'Anbieter'}</span><span>${date(t.messages.at(-1).at).slice(0,5)}</span></div><h3>${userText(t.subject)}</h3><p>${userText(t.role==='user'?d.user:d.provider)}</p><div class="ticket-bottom"><span>${t.dealId}</span>${t.priority==='high'&&t.status==='open'?'<span class="priority">Hohe Priorität</span>':`<span class="ticket-status ${t.status}">${t.status==='open'?'Offen':'Erledigt'}</span>`}</div></button>`;}).join('')||'<div class="empty small-empty">Keine Anfragen gefunden.</div>'}</div></div><div class="inbox-conversation">${selected?conversation(selected,false):'<div class="empty">'+icon('chat')+'<h3>Hier ist alles geklärt</h3><p>Wähle „Alle“, um frühere Anfragen anzusehen.</p></div>'}</div></section>`;}
function conversation(t,compact){const d=state.deals.find(x=>x.id===t.dealId),name=t.role==='user'?d.user:d.provider;return `<div class="conversation-head"><div><div class="eyebrow">${t.id} · ${t.role==='user'?'MITGLIED':'ANBIETER'}</div><h2>${userText(t.subject)}</h2><p>${esc(name)} <span>·</span> <span class="ticket-status ${t.status}">${t.status==='open'?'Offen':'Erledigt'}</span></p></div><button class="button ${t.status==='open'?'white':'primary'} compact" data-resolve="${t.id}">${icon(t.status==='open'?'check':'refresh')}${t.status==='open'?'Erledigen':'Wieder öffnen'}</button></div>${!compact?`<button class="linked-deal" data-open="${d.id}"><span>${icon('deal')}<strong>${d.id}</strong> ${userText(d.offer)}</span><span>${money(d.cashback)} ${icon('chevron')}</span></button>`:''}<div class="messages">${t.messages.map(m=>`<div class="message ${m.from==='admin'?'outgoing':m.from==='internal'?'internal':'incoming'}"><div class="message-author">${m.from==='admin'?'Ejdat Akyol · Admin':m.from==='internal'?icon('lock')+' Interne Notiz · Admin':esc(name)}<time>${date(m.at)} · ${time(m.at)}</time></div><p>${userText(m.text)}</p></div>`).join('')}<div class="thread-note">${icon('lock')} Demo-Unterhaltung · keine Nachricht wird extern versendet</div></div>${t.status==='open'?`<form class="reply-form" data-reply="${t.id}"><label for="reply-type-${t.id}" class="sr-only">Nachrichtenart</label><select id="reply-type-${t.id}" name="replyType"><option value="reply">Antwort an ${t.role==='user'?'Mitglied':'Anbieter'}</option><option value="internal">Interne Notiz</option></select><label class="sr-only" for="reply-${t.id}">Nachricht</label><textarea id="reply-${t.id}" name="message" maxlength="3000" required placeholder="Schreibe eine klare, hilfreiche Antwort …">${esc(drafts[t.id]||'')}</textarea><div class="composer-bottom"><span>Nur im Prototyp gespeichert</span><button class="button primary" type="submit">Antwort speichern ${icon('send')}</button></div></form>`:`<div class="resolved-note">${icon('check')} Diese Anfrage ist erledigt. Öffne sie wieder, um zu antworten.</div>`}`;}
function drawerHTML(){const d=state.deals.find(x=>x.id===drawer),tickets=state.tickets.filter(t=>t.dealId===d.id);return `<div class="backdrop" data-action="close-drawer"></div><section class="drawer ${detailTab==='reviews'?'reviews-drawer':''}" role="dialog" aria-modal="true" aria-labelledby="drawer-title" tabindex="-1"><div class="drawer-head"><div>${accountReturn?'<button class="account-back" data-account-action="return-profile">← Zurück zum Kontoprofil</button>':''}<div class="eyebrow">DEALDETAILS</div><h2 id="drawer-title">${d.id}</h2></div><button id="close-drawer" class="icon-button" data-action="close-drawer" aria-label="Detailansicht schließen">${icon('close')}</button></div><div class="drawer-summary"><div class="deal-category-icon">${icon('deal')}</div><div><h3>${userText(d.offer)}</h3><p>${userText(d.provider)} <span>·</span> ${esc(classificationLabel(d))}</p></div><div class="drawer-amount">${money(d.cashback)}<small>Cashback für Mitglied</small></div></div><div class="drawer-tabs">${[['overview','Überblick'],['payment','Zahlung & Cashback'],['history','Verlauf'],['reviews','Bewertungen & Streitfall'],['questions','Rückfragen'+(tickets.length?' ('+tickets.length+')':'')]].map(([v,l])=>`<button data-detail-tab="${v}" class="${detailTab===v?'selected':''}" aria-pressed="${detailTab===v}">${l}</button>`).join('')}</div><div class="drawer-body">${detailTab==='overview'?overviewDetail(d,tickets):detailTab==='payment'?paymentDetail(d):detailTab==='history'?historyDetail(d):detailTab==='reviews'?adminReviewDetail(state,d.id,{draft:drafts['review-case-'+d.id]||{},saved:reviewCaseSavedId===d.id}):questionsDetail(d,tickets)}</div></section>`;}
function overviewDetail(d,tickets){return `<div class="detail-section status-section"><div><div class="field-label">Aktueller Dealstatus</div>${pill(d.status)}</div><button class="button white compact" data-action="status" ${!ALLOWED[d.status].length?'disabled':''}>Status ändern ${icon('down')}</button></div><div class="progress-steps">${['requested','review','confirmed','completed'].map((s,i)=>`<div class="progress-step ${d.status!=='cancelled'&&['requested','review','confirmed','completed'].indexOf(d.status)>=i?'done':''}"><span>${d.status!=='cancelled'&&['requested','review','confirmed','completed'].indexOf(d.status)>i?icon('check'):i+1}</span><small>${DL[s]}</small></div>`).join('')}</div>${d.status==='cancelled'?'<div class="inline-alert">Dieser Deal wurde storniert. Es ist keine Auszahlung vorgesehen.</div>':''}<h3 class="section-title">Beteiligte</h3><div class="party-grid"><div class="party"><span class="avatar large">${initials(d.user)}</span><div><span class="field-label">Mitglied</span><button class="account-name-button" data-account-type="member" data-account-id="${esc(d.userId)}">${userText(d.user)} ${icon('external')}</button><small>${d.userId} · ${d.user.toLowerCase().replaceAll(' ','.')}@example.test</small><span class="mini-tag">Identität · Demo verifiziert</span></div></div><div class="party"><span class="company-avatar">${icon('building')}</span><div><span class="field-label">Anbieter</span><button class="account-name-button" data-account-type="provider" data-account-id="${esc(d.providerId)}">${userText(d.provider)} ${icon('external')}</button><small>${d.providerId} · partner@example.test</small><span class="mini-tag">Anbieter · Demo verifiziert</span></div></div></div>${purchasePanel(state,d,'admin')}${providerWorkflowPanel(state,d,'admin')}<h3 class="section-title">Deal & Vereinbarung</h3><div class="detail-section"><dl class="facts"><div><dt>Vertragsreferenz</dt><dd>${d.contract}</dd></div><div><dt>Angenommen am</dt><dd>${date(d.created)} · ${time(d.created)}</dd></div><div><dt>Prämienbedingung</dt><dd>${esc(d.snapshot?.conditions||'Bestätigung des Abschlusses und erfüllte Prämienbedingungen.')}</dd></div><div><dt>Nachweisstatus</dt><dd>${d.status==='cancelled'?'Durch Stornierung erledigt':d.proof?esc(d.proof.reference):'Nachweis noch ausstehend'}</dd></div></dl></div><button class="detail-payment-link" data-detail-tab="payment"><span>${icon('wallet')}<span><strong>Zahlung & Cashback</strong><small>${PL[d.payment]} · ${d.funded?'Budget gedeckt':'Budgetdeckung ausstehend'}</small></span></span><strong>${money(d.cashback)} ${icon('chevron')}</strong></button>${tickets.some(t=>t.status==='open')?`<button class="detail-ticket-link" data-detail-tab="questions">${icon('chat')} ${tickets.filter(t=>t.status==='open').length} offene Rückfrage zu diesem Deal ${icon('arrow')}</button>`:''}<h3 class="section-title">Bewertungen zum Deal</h3><button class="button white compact" data-detail-tab="reviews">Bewertungen & Streitfall öffnen</button><div class="deal-review-grid">${reviewsForDeal(state,d.id).map(r=>reviewCard(state,r,false)).join('')||'<p class="subtle">Für diesen Deal gibt es noch keine Bewertungen.</p>'}</div><p class="detail-footnote">Alle Namen, Verträge und Nachweisangaben sind fiktive Beispieldaten.</p>`;}
function originalPaymentDetail(d){const index=['pending','released','processing','paid'].indexOf(d.payment);return `<div class="cashback-hero"><div><span>CASHBACK FÜR DAS MITGLIED</span><strong>${money(d.cashback)}</strong><small>Kein Abzug der BuyMe-Servicegebühr</small></div>${pill(d.payment,'payment')}</div>${d.payment==='failed'?`<div class="payment-alert">${icon('alert')}<div><strong>Auszahlung fehlgeschlagen</strong><p>Das Empfängerkonto ist im Beispielszenario nicht vollständig verifiziert. Kein Geld abgeflossen. Verifizierung mit dem Mitglied klären.</p></div></div>`:''}<h3 class="section-title">Zahlungsfluss</h3><div class="payment-flow">${[['Budget','Anbieter finanziert',d.funded],['Freigabe','Prämie bestätigt',index>=1||d.payment==='failed'],['Auszahlung',d.payment==='failed'?'Fehlgeschlagen':'Zahlungsdienst',d.payment==='failed'?'error':index>=2],['Erhalten','Mitglied / Wallet',index>=3]].map(([t,l,done])=>`<div class="flow-step ${done==='error'?'error':done?'done':''}"><span>${icon(done==='error'?'alert':done?'check':'clock')}</span><strong>${t}</strong><small>${l}</small></div>`).join('')}</div><div class="detail-section"><dl class="facts"><div><dt>Budgetdeckung</dt><dd class="${d.funded?'text-green':'text-amber'}">${d.funded?'Durch Anbieter gedeckt':'Noch nicht gedeckt'}</dd></div><div><dt>Zahlungsreferenz</dt><dd class="mono">${d.paymentRef}</dd></div><div><dt>Voraussichtliche Freigabe</dt><dd>${['paid','failed','stopped'].includes(d.payment)?'—':date(d.due)+' · abhängig von Dealprüfung'}</dd></div><div><dt>Zahlungsdienst</dt><dd>Zahlungsdienst · simulierte Statusdaten</dd></div><div><dt>Cashback</dt><dd>${money(d.cashback)}</dd></div><div><dt>Servicegebühr des Anbieters</dt><dd>${money(d.fee)} <small>(Beispielannahme 10 %)</small></dd></div><div class="total"><dt>Beispiel-Gesamtbelastung Anbieter</dt><dd>${money(d.cashback+d.fee)}</dd></div></dl></div><p class="detail-footnote">Die 10 % dienen ausschließlich zur Demonstration. Die tatsächliche Servicegebühr und PSP-Kosten sind nicht hinterlegt. Die Servicegebühr trägt der Anbieter zusätzlich zum Cashback.</p>${d.payment==='pending'?`<div class="release-box"><div><strong>Freigabe simulieren</strong><p>${d.status==='completed'&&d.funded?'Die Voraussetzungen sind erfüllt. Du kannst die Freigabe lokal dokumentieren.':'Erst möglich, wenn der Deal abgeschlossen und das Anbieterbudget gedeckt ist.'}</p></div><button class="button primary" data-action="release" ${d.status!=='completed'||!d.funded?'disabled':''}>${icon('check')} Freigabe simulieren</button></div>`:`<div class="finance-note">${icon('lock')} <span>Der Zahlungsstatus stammt aus dem Beispielszenario. Es werden keine echten Zahlungen ausgelöst.</span></div>`}`;}
function historyDetail(d){const events=[...d.events].sort((a,b)=>b.at.localeCompare(a.at));return `<div class="history-heading"><h3>Vollständiger Statusverlauf</h3><span class="count">${events.length} Ereignisse</span></div><p class="subtle history-desc">Deal, Zahlung und Kommunikation in einer gemeinsamen Zeitleiste.</p><ol class="timeline">${events.map(e=>`<li><span class="timeline-icon ${e.kind}">${icon(e.kind==='payment'?'wallet':e.kind==='message'?'chat':'check')}</span><div><div class="event-top"><span class="event-type">${{deal:'DEALSTATUS',payment:'ZAHLUNG',message:'KOMMUNIKATION'}[e.kind]}</span><time>${date(e.at)} · ${time(e.at)}</time></div><h4>${esc(e.title)}</h4><p>${esc(e.detail)}</p><small>${esc(e.actor)}</small></div></li>`).join('')}</ol>`;}
function originalQuestionsDetail(d,tickets){if(!tickets.length)return `<div class="empty">${icon('chat')}<h3>Keine Rückfragen zu diesem Deal</h3><p>Neue Anfragen würden hier und im Posteingang erscheinen.</p></div>`;return `<div class="related-tickets">${tickets.map(t=>`<div class="compact-thread">${conversation(t,true)}</div>`).join('')}</div>`;}
function renderOverlay(){const d=accountDrawer?accountDrawerHTML():drawerHTMLSafe();$('#overlay').innerHTML=d+(modal?modalHTML():'');$('#app').inert=!!drawer||!!accountDrawer||!!modal;const el=$('.drawer');if(el)el.inert=!!modal;}
function drawerHTMLSafe(){return drawer?drawerHTML():'';}
function modalHTML(){const d=state.deals.find(x=>x.id===drawer);let content='';if(modal==='status'){content=`<div class="modal-icon">${icon('refresh')}</div><h2 id="modal-title">Dealstatus ändern</h2><p>${drawer} · Aktuell: ${DL[d.status]}</p><form id="status-form"><label>Neuer Status<select name="status" required>${ALLOWED[d.status].map(s=>option(s,DL[s],'')).join('')}</select></label><label>Grund für die Änderung<textarea name="reason" required minlength="5" maxlength="1000" placeholder="Was wurde geprüft oder vereinbart?"></textarea></label><div class="modal-note">Die Änderung wird mit Zeitpunkt und Begründung im Verlauf gespeichert. Der Zahlungsstatus wird separat geführt. Bei einer zulässigen Stornierung wird das Cashback gestoppt.</div><div id="form-error" class="form-error" role="alert"></div><div class="modal-actions"><button class="button white" type="button" data-action="close-modal">Abbrechen</button><button class="button primary" type="submit">Änderung speichern</button></div></form>`;}
else if(modal==='release'){content=`<div class="modal-icon">${icon('wallet')}</div><h2 id="modal-title">Freigabe simulieren?</h2><p>Für ${drawer} werden ${money(d.cashback)} als freigegeben markiert. Diese Aktion verändert nur die Beispieldaten in diesem Browser.</p><div class="modal-actions"><button class="button white" data-action="close-modal">Abbrechen</button><button class="button primary" data-action="confirm-release">Freigabe bestätigen</button></div>`;}
else if(modal==='reset'){content=`<div class="modal-icon">${icon('refresh')}</div><h2 id="modal-title">Demo zurücksetzen?</h2><p>Deine lokal gespeicherten Antworten, Notizen und Statusänderungen werden entfernt. Die ursprünglichen Beispieldaten werden wiederhergestellt.</p><div class="modal-actions"><button class="button white" data-action="close-modal">Abbrechen</button><button class="button danger" data-action="confirm-reset">Demo zurücksetzen</button></div>`;}
else {content=`<div class="modal-icon">${icon('lock')}</div><h2 id="modal-title">Dein privates Admin Cockpit</h2><p>Dieser Prototyp zeigt, wie BuyMe Deals und die zugehörige Kommunikation zentral steuern kann.</p><ul class="info-list"><li>${icon('check')} Deals suchen, filtern und vollständig nachverfolgen</li><li>${icon('check')} Deal- und Cashbackstatus getrennt prüfen</li><li>${icon('check')} Anfragen beantworten, intern notieren und erledigen</li><li>${icon('check')} Statuswechsel mit Begründung dokumentieren</li></ul><div class="modal-note"><strong>Zum Ausprobieren</strong><br>Mitglieder, Anbieter und Admin verwenden dieselben Testdaten. Änderungen bleiben in diesem Browser erhalten. Keine Live-Verbindung zu BuyMe oder einem Zahlungsdienst. Nachrichten und Geldbewegungen werden simuliert. Private Bereitstellung über Sites.</div><div class="modal-actions spread"><button class="text-button" data-action="reset">Demo zurücksetzen</button><button class="button primary" data-action="close-modal">Verstanden</button></div>`;}
return `<div class="modal-backdrop" data-action="close-modal"></div><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><button class="icon-button modal-close" data-action="close-modal" aria-label="Dialog schließen">${icon('close')}</button>${content}</section>`;}
function openDetail(id,tab='overview',keepAccount=false){if(!keepAccount)accountReturn=null;accountDrawer=null;drawer=id;detailTab=tab;renderOverlay();document.body.classList.add('no-scroll');requestAnimationFrame(()=>$('#close-drawer')?.focus());}
function openModal(kind){modal=kind;renderOverlay();document.body.classList.add('no-scroll');requestAnimationFrame(()=>$('.modal')?.focus());}
function closeModal(){modal=null;renderOverlay();if(!drawer&&!accountDrawer)document.body.classList.remove('no-scroll');requestAnimationFrame(()=>drawer||accountDrawer?$('#close-drawer')?.focus():$('.help-link')?.focus());}
function closeDrawer(){if(accountReturn){accountDrawer=accountReturn;accountReturn=null;drawer=null;renderOverlay();requestAnimationFrame(()=>$('#close-drawer')?.focus());return;}drawer=null;accountDrawer=null;renderOverlay();document.body.classList.remove('no-scroll');requestAnimationFrame(()=>$(page==='reviews'?'#admin-review-search':page==='people'?'#people-search':'#deal-search')?.focus());}
function exportCSV(){const rows=selectDeals(state,filters);const lines=[['Deal-ID','Mitglied','Anbieter','Angebot','Hauptkategorie','Unterkategorie','Cashback EUR','Dealstatus','Zahlungsstatus','Budget gedeckt','Erstellt'],...rows.map(d=>[d.id,d.user,d.provider,d.offer,categoryName(d.category),d.subcategory||'',d.cashback.toFixed(2).replace('.',','),DL[d.status],PL[d.payment],d.funded?'Ja':'Nein',date(d.created)])];const csv='\uFEFF'+lines.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='BuyMe_Deals_Beispieldaten.csv';a.click();URL.revokeObjectURL(url);toast(rows.length+' Deals als CSV exportiert.');}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b||b.disabled)return;if(b.matches('.brand')){e.preventDefault();page='deals';filters={q:'',dealStatus:'',paymentStatus:'',category:'',subcategory:'',scope:'all',sort:'newest'};render();return;}
if(b.dataset.nav){page=b.dataset.nav;filters={q:'',dealStatus:'',paymentStatus:'',category:'',subcategory:'',scope:'all',sort:'newest'};pageNo=1;render();return;}
if(b.dataset.open){openDetail(b.dataset.open,b.dataset.detail||'overview');return;}
if(b.dataset.scope){filters.scope=b.dataset.scope;pageNo=1;render();return;}
if(b.dataset.page){pageNo=+b.dataset.page;render();return;}
if(b.dataset.detailTab){detailTab=b.dataset.detailTab;renderOverlay();$('.drawer-body').scrollTop=0;return;}
if(b.dataset.ticket){ticketId=b.dataset.ticket;render();return;}
if(b.dataset.inboxFilter){inboxFilter=b.dataset.inboxFilter;render();return;}
if(b.dataset.resolve){const t=state.tickets.find(x=>x.id===b.dataset.resolve);setTicketStatus(state,t.id,t.status==='open'?'resolved':'open');save();render();toast(t.status==='resolved'?'Anfrage als erledigt markiert.':'Anfrage wieder geöffnet.');return;}
const action=b.dataset.action;if(action==='info')openModal('info');if(action==='reset')openModal('reset');if(action==='close-modal')closeModal();if(action==='close-drawer')closeDrawer();if(action==='status')openModal('status');if(action==='release')openModal('release');if(action==='clear'){filters={q:'',dealStatus:'',paymentStatus:'',category:'',subcategory:'',scope:'all',sort:'newest'};pageNo=1;render();}if(action==='attention'){filters.scope='attention';pageNo=1;render();$('.table-card')?.scrollIntoView({behavior:'smooth',block:'start'});}if(action==='export')exportCSV();if(action==='confirm-release'){try{releasePayment(state,drawer);save();modal=null;render();toast('Freigabe simuliert. Kein echter Zahlungsauftrag.');}catch(err){toast(err.message);}}if(action==='confirm-reset'){state=createSeed();drafts={};save();modal=null;drawer=null;accountDrawer=null;accountReturn=null;document.body.classList.remove('no-scroll');render();toast('Die ursprünglichen Beispieldaten sind wiederhergestellt.');}
});
document.addEventListener('click',e=>{if(e.target.matches('.backdrop'))closeDrawer();if(e.target.matches('.modal-backdrop'))closeModal();});
document.addEventListener('input',e=>{if(e.target.id==='deal-search'){filters.q=e.target.value;pageNo=1;render();}if(e.target.id==='inbox-search'){inboxSearch=e.target.value;render();}if(e.target.name==='message'){const id=e.target.closest('form').dataset.reply;drafts[id]=e.target.value;}});
document.addEventListener('change',e=>{const map={'filter-deal':'dealStatus','filter-payment':'paymentStatus','filter-category':'category','sort':'sort'};if(e.target.id==='filter-subcategory'){filters.subcategory=e.target.value;pageNo=1;render();}if(map[e.target.id]){if(e.target.id==='filter-category')filters.subcategory='';filters[map[e.target.id]]=e.target.value;pageNo=1;render();}if(e.target.name==='replyType'){const form=e.target.closest('form'),internal=e.target.value==='internal';form.querySelector('button[type=submit]').innerHTML=(internal?'Notiz speichern':'Antwort speichern')+icon(internal?'note':'send');form.querySelector('textarea').placeholder=internal?'Interne Notiz – nur für die Administration …':'Schreibe eine klare, hilfreiche Antwort …';form.classList.toggle('internal-mode',internal);}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='status-form'){const f=new FormData(e.target);try{changeDeal(state,drawer,f.get('status'),f.get('reason'));save();modal=null;render();toast('Dealstatus und Verlauf aktualisiert.');$('#close-drawer')?.focus();}catch(err){$('#form-error').textContent=err.message;}}if(e.target.dataset.reply){const id=e.target.dataset.reply,f=new FormData(e.target);try{const internal=f.get('replyType')==='internal';reply(state,id,f.get('message'),internal);drafts[id]='';save();render();toast(internal?'Interne Notiz gespeichert.':'Demo-Antwort gespeichert.');document.getElementById('reply-'+id)?.focus();}catch(err){toast(err.message);}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(modal)closeModal();else if(drawer||accountDrawer)closeDrawer();}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!drawer&&!accountDrawer&&!modal){e.preventDefault();$(page==='reviews'?'#admin-review-search':page==='inbox'?'#inbox-search':'#deal-search')?.focus();}if(e.key==='Tab'&&(modal||drawer||accountDrawer)){const container=$(modal?'.modal':'.drawer'),els=[...container.querySelectorAll('button:not([disabled]),input,select,textarea,a[href]')].filter(x=>x.offsetParent!==null);const first=els[0],last=els.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===container)){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('storage',e=>{if(e.key===KEY||e.key===Auth.AUTH_SESSION_KEY){state=loadState();render();}});
window.addEventListener('pageshow',e=>{if(e.persisted){state=loadState();render();}});
render();
const incomingAccount=new URLSearchParams(location.search).get('account');
const incomingType=new URLSearchParams(location.search).get('type');
if(Auth.currentAuth(state)?.role==='admin'&&incomingAccount&&accountContext(state,incomingType,incomingAccount)){page='people';render();openAccount(incomingType,incomingAccount);}
const incomingDeal=new URLSearchParams(location.search).get('deal');
if(Auth.currentAuth(state)?.role==='admin'&&incomingDeal&&state.deals.some(d=>d.id===incomingDeal))openDetail(incomingDeal);
function paymentDetail(d){return purchasePanel(state,d,'admin')+originalPaymentDetail(d)+paymentSimulationActions(d);}
function paymentSimulationActions(d){if(d.payment==='processing')return `<div class="simulation-actions"><h3>Demo-Zahlungsdienst steuern</h3><p>Schließe die angeforderte Auszahlung ab oder simuliere einen Fehler. Beide Ergebnisse erscheinen im Verlauf und in der Wallet des Mitglieds.</p><div><button class="button primary" data-platform="paid" data-id="${d.id}">Auszahlung erfolgreich simulieren</button></div><label>Fehlergrund für eine fehlgeschlagene Auszahlung<input id="payment-error-${d.id}" placeholder="z. B. Kontoverifizierung im Test unvollständig"></label><button class="button white" data-platform="failed" data-id="${d.id}">Fehlschlag simulieren</button></div>`;if(d.payment==='failed')return `<div class="simulation-actions"><h3>Auszahlungsfehler klären</h3><p>${esc(d.paymentError||'Empfängerkonto im Beispielszenario nicht vollständig verifiziert.')}</p><button class="button primary" data-platform="retry" data-id="${d.id}">Fehler geklärt · erneut freigeben</button><p>Danach kann das Mitglied die Auszahlung erneut in der Wallet anfordern.</p></div>`;return '';}
function offerModerationPage(){const q=moderationQuery.toLowerCase(),os=state.offers.filter(o=>!q||[o.id,o.title,state.providers.find(p=>p.id===o.providerId)?.name,categoryName(o.category),o.subcategory].some(v=>v?.toLowerCase().includes(q))).sort((a,b)=>(a.status==='pending'?-1:1)-(b.status==='pending'?-1:1));return `<section class="stats">${statCard('Angebote gesamt',state.offers.length,'Alle Angebote in der Testplattform','grid')}${statCard('Warten auf Prüfung',state.offers.filter(o=>o.status==='pending').length,'Noch nicht im Marktplatz sichtbar','clock','amber')}${statCard('Aktive Angebote',state.offers.filter(o=>o.status==='active').length,'Im Marktplatz freigegeben','check')}${statCard('Pausiert / zurückgewiesen',state.offers.filter(o=>['paused','rejected'].includes(o.status)).length,'Bestehende Deals bleiben erhalten','deal')}</section><div class="table-card"><div class="card-top"><h2>Angebote prüfen</h2><a class="admin-platform-link" href="./?role=provider#offer-new">Als Anbieter ein Angebot erstellen →</a></div><div class="filter-bar"><label class="searchbox">${icon('search')}<input id="moderation-search" aria-label="Angebote zur Moderation suchen" placeholder="Angebot oder Anbieter suchen …" value="${esc(moderationQuery)}"></label></div><div class="moderation-list">${os.map(o=>{const p=state.providers.find(p=>p.id===o.providerId);return `<article class="moderation-offer"><div class="moderation-title"><span class="company-avatar">${icon('deal')}</span><div><span class="mono">${o.id} · ${userText(p.name)}</span><h3>${userText(o.title)}</h3><p>${esc(classificationLabel(o))} · ${userText(o.price)} · ${userText(o.region)}</p></div><span class="badge ${o.status==='pending'?'review':o.status==='active'?'completed':o.status==='rejected'?'failed':'cancelled'}">${{active:'Aktiv',pending:'Freigabe offen',paused:'Pausiert',rejected:'Zurückgewiesen'}[o.status]}</span></div><div class="moderation-facts"><span>Mitglied erhält <strong>${money(o.cashback)}</strong></span><span>Gesamtes Budget <strong>${money(o.budget)}</strong></span><span>Noch frei <strong>${money(Platform.offerAvailable(state,o))}</strong></span></div><p>${userText(o.description)}</p><details><summary>Prämienbedingungen & Prüfung</summary><p>${userText(o.conditions)}</p><p>Prüffrist im Testszenario: ${o.payoutDays} Tage · Gültig bis ${date(o.validUntil+'T12:00:00Z')}</p></details>${o.status==='pending'?`<div class="moderation-actions"><button class="button primary" data-platform="approve-offer" data-id="${o.id}">Angebot freigeben</button><input id="reject-note-${o.id}" aria-label="Begründung für ${o.id}" placeholder="Begründung für Zurückweisung"><button class="button white" data-platform="reject-offer" data-id="${o.id}">Zurückweisen</button></div>`:`<div class="moderation-result">${esc(o.moderationNote||'Das Angebot wurde durch den Anbieter pausiert.')}</div>`}</article>`;}).join('')||'<div class="empty">Keine passenden Angebote.</div>'}</div></div>`;}
document.addEventListener('input',e=>{if(e.target.id==='moderation-search'){moderationQuery=e.target.value;render();}});
document.addEventListener('click',e=>{const b=e.target.closest('button[data-platform]');if(!b)return;const id=b.dataset.id,a=b.dataset.platform;try{let message='Testdaten aktualisiert.';if(a==='approve-offer'){Platform.moderateOffer(state,id,true,'');message='Angebot freigegeben. Es ist im Marktplatz sichtbar.';}if(a==='reject-offer'){Platform.moderateOffer(state,id,false,document.getElementById('reject-note-'+id).value);message='Angebot mit Begründung zurückgewiesen.';}if(a==='verify-provider'){Platform.verifyProvider(state,id);message='Anbieter für den Test verifiziert.';}if(a==='paid'){Platform.settlePayment(state,id,true);message='Auszahlung als erfolgreich simuliert.';}if(a==='failed'){Platform.settlePayment(state,id,false,document.getElementById('payment-error-'+id).value);message='Auszahlungsfehler simuliert.';}if(a==='retry'){Platform.retryPayment(state,id);message='Cashback erneut für die Auszahlung freigegeben.';}if(a==='account-member'||a==='account-provider'){const type=a==='account-member'?'member':'provider',item=(type==='member'?state.members:state.providers).find(x=>x.id===id);Platform.setAccountStatus(state,type,id,item.status!=='active');message='Demokonto aktualisiert.';}save();render();toast(message);}catch(err){toast(err.message);}});

function questionsDetail(d,tickets){return (d.messages?.length?`<section class="compact-thread"><div class="conversation-head"><div><div class="eyebrow">MITGLIED ↔ ANBIETER</div><h2>Nachrichten zu ${d.id}</h2><p>Vollständige Unterhaltung zum Deal</p></div></div><div class="messages">${d.messages.map(m=>`<div class="message ${m.from==='provider'?'outgoing':'incoming'}"><div class="message-author">${userText(m.from==='user'?d.user:d.provider)}<time>${date(m.at)} · ${time(m.at)}</time></div><p>${userText(m.text)}</p></div>`).join('')}</div></section>`:'')+originalQuestionsDetail(d,tickets);}
function accountNameButton(type,a){return `<button class="account-name-button" data-account-type="${type}" data-account-id="${esc(a.id)}">${userText(a.name)} ${icon('chevron')}</button>`;}
function peoplePage(){const q=peopleQuery.trim().toLocaleLowerCase('de'),match=a=>!q||[a.name,a.id,a.email,a.city,a.region,a.contactName,a.contact].some(v=>String(v||'').toLocaleLowerCase('de').includes(q)),members=state.members.filter(match),providers=state.providers.filter(match);return `<div class="account-search-panel"><label class="searchbox">${icon('search')}<input id="people-search" aria-label="Mitglieder und Anbieter durchsuchen" placeholder="Name, Firma, E-Mail, Kontonummer oder Ort suchen …" value="${esc(peopleQuery)}"></label><span>${members.length} Mitglieder · ${providers.length} Anbieter</span>${q?'<button class="text-button" data-account-action="clear-search">Suche zurücksetzen</button>':''}</div><section class="table-card"><div class="card-top"><h2>Mitglieder <span class="count">${members.length}</span></h2><span class="subtle">Name oder „Details“ öffnet das vollständige Kontoprofil.</span></div><div class="table-scroll"><table><thead><tr><th>Mitglied / Kontonummer</th><th>E-Mail / Ort</th><th>Deals</th><th>Status</th><th>Aktionen</th></tr></thead><tbody>${members.map(u=>`<tr><td><div class="account-table-identity"><span class="avatar">${initials(u.name)}</span><div>${accountNameButton('member',u)}<div class="cell-sub">${esc(u.id)}</div></div></div></td><td>${userText(u.email||'Nicht hinterlegt')}<div class="cell-sub">${esc(u.city||'Ort nicht hinterlegt')}</div></td><td>${state.deals.filter(d=>d.userId===u.id).length}</td><td><span class="badge ${u.status==='active'?'completed':'cancelled'}">${u.status==='active'?'Aktiv':'Gesperrt'}</span></td><td><div class="account-table-actions"><button class="button white compact" data-account-type="member" data-account-id="${esc(u.id)}" aria-label="Details zu Mitglied ${esc(u.name)}">Details ${icon('chevron')}</button><button class="text-button" data-platform="account-member" data-id="${esc(u.id)}">${u.status==='active'?'Sperren':'Aktivieren'}</button></div></td></tr>`).join('')||'<tr><td colspan="5"><div class="account-table-empty">Keine passenden Mitglieder gefunden.</div></td></tr>'}</tbody></table></div></section><section class="table-card accounts-provider"><div class="card-top"><h2>Anbieter <span class="count">${providers.length}</span></h2><span class="subtle">Firmenprofil, Ansprechpartner und zugehörige Geschäfte einsehen.</span></div><div class="table-scroll"><table><thead><tr><th>Anbieter / Kontonummer</th><th>Kontakt / Region</th><th>Angebote / Deals</th><th>Status</th><th>Aktionen</th></tr></thead><tbody>${providers.map(p=>`<tr><td><div class="account-table-identity"><span class="company-avatar">${icon('building')}</span><div>${accountNameButton('provider',p)}<div class="cell-sub">${esc(p.id)}</div></div></div></td><td>${esc(p.email||'Nicht hinterlegt')}<div class="cell-sub">${userText(p.region||'Region nicht hinterlegt')}</div></td><td>${state.offers.filter(o=>o.providerId===p.id).length} Angebote<div class="cell-sub">${state.deals.filter(d=>d.providerId===p.id).length} Deals</div></td><td><span class="badge ${p.status==='active'?'completed':'cancelled'}">${p.status==='active'?'Aktiv':'Gesperrt'}</span><div class="cell-sub">${p.verified?'Demo-verifiziert':'Verifizierung offen'}</div></td><td><div class="account-table-actions"><button class="button white compact" data-account-type="provider" data-account-id="${esc(p.id)}" aria-label="Details zu Anbieter ${esc(p.name)}">Details ${icon('chevron')}</button>${!p.verified?`<button class="text-button" data-platform="verify-provider" data-id="${esc(p.id)}">Verifizieren</button>`:''}<button class="text-button" data-platform="account-provider" data-id="${esc(p.id)}">${p.status==='active'?'Sperren':'Aktivieren'}</button></div></td></tr>`).join('')||'<tr><td colspan="5"><div class="account-table-empty">Keine passenden Anbieter gefunden.</div></td></tr>'}</tbody></table></div></section><section class="table-card admin-activity"><div class="card-top"><h2>Plattformaktivität</h2></div>${state.activity.slice(0,20).map(a=>`<div class="activity-row"><strong>${esc(a.title)}</strong><p>${esc(a.detail)}</p><small>${date(a.at)} · ${time(a.at)} · ${esc(a.actor)}</small></div>`).join('')||'<div class="account-table-empty">Neue Freigaben und Kontoveränderungen erscheinen hier.</div>'}</section>`;}
function openAccount(type,id){if(!accountContext(state,type,id))return;accountDrawer={type,id};accountTab='profile';accountReturn=null;drawer=null;modal=null;renderOverlay();document.body.classList.add('no-scroll');requestAnimationFrame(()=>$('#close-drawer')?.focus());}
function accountField(label,value){const missing=value===undefined||value===null||String(value).trim()==='';return `<div><dt>${label}</dt><dd class="${missing?'account-missing':''}">${missing?'Nicht hinterlegt':['Vollständiger Name','Firmenname','Ansprechpartner','Kontonummer','E-Mail-Adresse','Telefonnummer','Straße / Hausnummer','Postleitzahl','Wohnort','Firmensitz / Ort','Land','Website','Rechtsform','Handelsregister / Registernummer','USt-IdNr.'].includes(label)?userText(value):esc(value)}</dd></div>`;}
function accountDrawerHTML(){const c=accountContext(state,accountDrawer.type,accountDrawer.id);if(!c)return `<div class="backdrop"></div><section class="drawer" role="dialog" aria-modal="true" aria-label="Konto nicht mehr vorhanden"><button id="close-drawer" class="button white" data-action="close-drawer">Schließen</button><p>Dieses Demokonto ist nicht mehr vorhanden.</p></section>`;const a=c.account,isMember=c.type==='member',tabs=[['profile','Profil & Kontakt'],['deals','Deals ('+c.deals.length+')'],...(!isMember?[['offers','Angebote ('+c.offers.length+')']]:[]),['tickets','Rückfragen ('+c.tickets.length+')'],['reviews','Bewertungen ('+c.reviews.length+')'],['history','Verlauf']];return `<div class="backdrop" data-action="close-drawer"></div><section class="drawer account-drawer" role="dialog" aria-modal="true" aria-labelledby="account-drawer-title" tabindex="-1"><div class="drawer-head"><div><div class="eyebrow">${isMember?'MITGLIEDSPROFIL':'ANBIETERPROFIL'}</div><h2 id="account-drawer-title">${userText(a.name)}</h2></div><button id="close-drawer" class="icon-button" data-action="close-drawer" aria-label="Kontodetails schließen">${icon('close')}</button></div><div class="account-identity"><span class="${isMember?'avatar':'company-avatar'} account-avatar">${isMember?initials(a.name):icon('building')}</span><div><strong>${isMember?'Privates BuyMe-Mitglied':'Unternehmen / Anbieter'}</strong><span>${esc(a.id)} · ${userText(a.email||'E-Mail nicht hinterlegt')}</span></div><div class="account-identity-badges"><span class="badge ${a.status==='active'?'completed':'cancelled'}">${a.status==='active'?'Konto aktiv':'Konto gesperrt'}</span>${!isMember?`<span class="badge ${a.verified?'confirmed':'review'}">${a.verified?'Demo-verifiziert':'Verifizierung offen'}</span>`:''}</div></div><div class="drawer-tabs account-tabs">${tabs.map(([v,t])=>`<button data-account-tab="${v}" class="${accountTab===v?'selected':''}" aria-pressed="${accountTab===v}">${t}</button>`).join('')}</div><div class="drawer-body">${accountTab==='deals'?accountDeals(c):accountTab==='offers'?accountOffers(c):accountTab==='tickets'?accountTickets(c):accountTab==='reviews'?adminAccountReviewList(state,c):accountTab==='history'?accountHistory(c):accountProfile(c)}</div></section>`;}
function accountProfile(c){const a=c.account,m=c.type==='member',wallet=c.wallet;return `<section class="account-summary-stats">${m?`<div><span>Deals</span><strong>${c.deals.length}</strong></div><div><span>Vorgemerkt</span><strong>${money(wallet.pending)}</strong></div><div><span>Verfügbar</span><strong>${money(wallet.available)}</strong></div><div><span>Ausgezahlt</span><strong>${money(wallet.paid)}</strong></div>`:`<div><span>Angebote</span><strong>${c.offers.length}</strong></div><div><span>Kunden-Deals</span><strong>${c.deals.length}</strong></div><div><span>Freies Demo-Guthaben</span><strong>${money(c.budget.credit)}</strong></div><div><span>Reserviert / verbraucht</span><strong>${money(c.budget.used)}</strong></div>`}</section><div class="account-section-heading"><h3>${m?'Persönliche Stammdaten':'Firmenstammdaten'}</h3><span class="cell-sub">Angaben aus dem registrierten Konto</span></div><div class="detail-section"><dl class="facts account-facts">${accountField(m?'Vollständiger Name':'Firmenname',a.name)}${accountField('Kontonummer',a.id)}${!m?accountField('Rechtsform',a.legalForm):''}${accountField('Registriert am',a.createdAt?date(a.createdAt)+' · '+time(a.createdAt):null)}${accountField('Zuletzt im Profil geändert',a.updatedAt?date(a.updatedAt)+' · '+time(a.updatedAt):null)}${m?accountField('Interessen',a.interests?.join(', ')):accountField('Branchen / Kategorien',[...new Set(c.offers.map(o=>classificationLabel(o)))].join(', '))}</dl></div><h3 class="section-title">Kontakt & Anschrift</h3><div class="detail-section"><dl class="facts account-facts">${!m?accountField('Ansprechpartner',a.contactName||a.contact):''}${accountField('E-Mail-Adresse',a.email)}${accountField('Telefonnummer',a.phone)}${accountField('Straße / Hausnummer',a.address)}${accountField('Postleitzahl',a.postalCode)}${accountField(m?'Wohnort':'Firmensitz / Ort',m?a.city:(a.city||a.region))}${accountField('Land',a.country)}${!m?accountField('Website',a.website):''}</dl></div>${!m?`<h3 class="section-title">Firmenbeschreibung</h3><div class="detail-section"><p class="account-description">${esc(a.description||'Nicht hinterlegt')}</p></div><h3 class="section-title">Unternehmensangaben & Prüfstatus</h3><div class="detail-section"><dl class="facts account-facts">${accountField('Handelsregister / Registernummer',a.registerNumber)}${accountField('USt-IdNr.',a.vatId)}${accountField('Demo-Prüfstatus',a.verified?'Für den Test verifiziert':'Prüfung ausstehend')}${accountField('Demo-Verifizierung am',a.verifiedAt?date(a.verifiedAt)+' · '+time(a.verifiedAt):null)}</dl><p class="detail-footnote">Die Demo-Verifizierung ist keine echte Unternehmens- oder Identitätsprüfung. Es werden keine Ausweis- oder Registerdokumente vorgetäuscht.</p></div>`:''}<div class="account-note">${icon('help')}<span>Fehlende Angaben werden ausdrücklich markiert. Kontoinhaber können sie im eigenen Profil ergänzen; sie erscheinen anschließend auch hier. Bitte im Prototyp nur fiktive Angaben verwenden.</span></div><h3 class="section-title">Verknüpfte Vorgänge</h3><div class="account-shortcuts"><button data-account-tab="deals">${icon('deal')}<span><strong>${c.deals.length} Deals ansehen</strong><small>Verträge, Prämien und Verlauf</small></span>${icon('chevron')}</button><button data-account-tab="tickets">${icon('chat')}<span><strong>${c.tickets.length} Rückfragen ansehen</strong><small>Mitglieds- und Anbieteranfragen zu den Deals</small></span>${icon('chevron')}</button>${!m?`<button data-account-tab="offers">${icon('grid')}<span><strong>${c.offers.length} Angebote ansehen</strong><small>Prämien, Budget und Freigaben</small></span>${icon('chevron')}</button>`:''}</div><div class="account-management"><div><strong>Kontoverwaltung</strong><small>${a.status==='active'?'Dieses Demokonto ist aktiv.':'Dieses Demokonto ist gesperrt.'}</small></div><div>${!m&&!a.verified?`<button class="button primary compact" data-platform="verify-provider" data-id="${esc(a.id)}">Demo-Verifizierung</button>`:''}<button class="button white compact" data-platform="account-${c.type}" data-id="${esc(a.id)}">${a.status==='active'?'Konto sperren':'Konto aktivieren'}</button></div></div>`;}
function accountDeals(c){return `<div class="history-heading"><h3>Zugehörige Deals</h3><span class="count">${c.deals.length}</span></div><p class="subtle history-desc">Jeder Deal ist über die feste Kontonummer zugeordnet.</p><div class="account-related-list">${c.deals.map(d=>`<article><div><span class="mono">${d.id}</span><h4>${userText(d.offer)}</h4><p>${c.type==='member'?'Anbieter: '+esc(d.provider):'Mitglied: '+esc(d.user)} · ${date(d.created)}</p><div class="account-related-badges">${pill(d.status)}${pill(d.payment,'payment')}</div></div><div><strong>${money(d.cashback)}</strong><button class="button white compact" data-account-deal="${d.id}">Deal öffnen ${icon('arrow')}</button></div></article>`).join('')||'<div class="empty">Zu diesem Konto gibt es noch keine Deals.</div>'}</div>`;}
function accountOffers(c){return `<div class="history-heading"><h3>Angebote dieses Anbieters</h3><span class="count">${c.offers.length}</span></div><p class="subtle history-desc">Angebotskonditionen, Prämien und zugeteilte Budgets.</p><div class="account-related-list">${c.offers.map(o=>`<article><div><span class="mono">${o.id} · ${esc(classificationLabel(o))}</span><h4>${userText(o.title)}</h4><p>${userText(o.price)} · Budget ${money(o.budget)}</p><span class="badge ${o.status==='active'?'completed':o.status==='pending'?'review':o.status==='rejected'?'failed':'cancelled'}">${{active:'Aktiv',pending:'Freigabe offen',paused:'Pausiert',rejected:'Zurückgewiesen'}[o.status]}</span></div><div><strong>${money(o.cashback)}</strong><button class="button white compact" data-account-offer="${o.id}">Angebot prüfen ${icon('arrow')}</button></div></article>`).join('')||'<div class="empty">Dieser Anbieter hat noch keine Angebote erstellt.</div>'}</div>`;}
function accountTickets(c){return `<div class="history-heading"><h3>Rückfragen zu den Deals</h3><span class="count">${c.tickets.length}</span></div><p class="subtle history-desc">Anfragen beider Beteiligten werden im Zusammenhang mit dem Deal angezeigt.</p><div class="account-related-list">${c.tickets.map(t=>`<article><div><span class="mono">${t.id} · ${t.dealId}</span><h4>${userText(t.subject)}</h4><p>Von ${t.role==='user'?'Mitglied':'Anbieter'} · ${t.messages.length} Nachrichten</p><span class="badge ${t.status==='open'?'review':'completed'}">${t.status==='open'?'Offen':'Erledigt'}</span></div><button class="button white compact" data-account-ticket="${t.id}">Rückfrage öffnen ${icon('arrow')}</button></article>`).join('')||'<div class="empty">Zu den Deals dieses Kontos liegen keine Rückfragen vor.</div>'}</div>`;}
function accountHistory(c){return `<div class="history-heading"><h3>Verlauf über alle zugeordneten Deals</h3><span class="count">${c.events.length} Ereignisse</span></div><p class="subtle history-desc">Statuswechsel, Zahlungen und Kommunikation mit eindeutiger Dealreferenz.</p><ol class="timeline">${c.events.map(e=>`<li><span class="timeline-icon ${e.kind}">${icon(e.kind==='payment'?'wallet':e.kind==='message'?'chat':'check')}</span><div><div class="event-top"><button class="text-button" data-account-deal="${e.dealId}">${e.dealId}</button><time>${date(e.at)} · ${time(e.at)}</time></div><h4>${esc(e.title)}</h4><p>${esc(e.detail)}</p><small>${esc(e.actor)}</small></div></li>`).join('')||'<div class="empty">Noch keine Dealereignisse zu diesem Konto.</div>'}</ol>`;}
document.addEventListener('input',e=>{if(e.target.id==='people-search'){peopleQuery=e.target.value;render();}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.accountType){openAccount(b.dataset.accountType,b.dataset.accountId);return;}if(b.dataset.accountTab){accountTab=b.dataset.accountTab;renderOverlay();$('.drawer-body').scrollTop=0;requestAnimationFrame(()=>$('.account-tabs [aria-pressed="true"]')?.focus());return;}if(b.dataset.accountReview){accountReturn=accountDrawer;openDetail(b.dataset.accountReview,'reviews',true);return;}if(b.dataset.accountDeal){accountReturn=accountDrawer;openDetail(b.dataset.accountDeal,'overview',true);return;}if(b.dataset.accountTicket){accountDrawer=null;drawer=null;accountReturn=null;ticketId=b.dataset.accountTicket;inboxFilter='all';inboxSearch='';page='inbox';document.body.classList.remove('no-scroll');render();return;}if(b.dataset.accountOffer){accountDrawer=null;drawer=null;accountReturn=null;moderationQuery=b.dataset.accountOffer;page='offers';document.body.classList.remove('no-scroll');render();return;}if(b.dataset.accountAction==='return-profile'&&accountReturn){accountDrawer=accountReturn;accountReturn=null;drawer=null;renderOverlay();requestAnimationFrame(()=>$('#close-drawer')?.focus());}if(b.dataset.accountAction==='clear-search'){peopleQuery='';render();}});

installAdminReviewInteractions(document,{
 onFilter:values=>{adminReviewFilters={...adminReviewFilters,...values};render();},
 onClear:()=>{adminReviewFilters={q:'',direction:'',rating:'',caseStatus:''};render();},
 onDraft:(id,values)=>{drafts['review-case-'+id]=values;},
 onSave:(form,values)=>{try{const latest=loadState();saveAdminReviewCase(latest,form.dataset.dealId,Auth.currentAuth(latest),values);state=latest;drafts['review-case-'+form.dataset.dealId]={};reviewCaseSavedId=form.dataset.dealId;save();render();toast('Fallprüfung gespeichert.');}catch(error){const box=form.querySelector('.form-error');box.textContent=error.message;box.focus();}}
});

document.addEventListener('input',e=>{if(e.target.id==='admin-order-search'){adminOrderFilters.q=e.target.value;render();}});
document.addEventListener('change',e=>{if(e.target.id==='admin-order-status'){adminOrderFilters.status=e.target.value;render();}});
